function addDays(d, n){ return new Date(d.getTime() + n*86400000); }
function dueDate(lmp){ return addDays(lmp, 280); } // 40 周
function trimester2(lmp){ return addDays(lmp, 98); }
function trimester3(lmp){ return addDays(lmp, 196); }
function week(lmp, asOf){ return Math.floor((asOf - lmp)/86400000/7); }
var EXPORTS={addDays:addDays, dueDate:dueDate, trimester2:trimester2, trimester3:trimester3, week:week};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PregnancyForgePure = EXPORTS; }
